/**
 * Parse new waitlist entry
 * Calculate waitlist position
 * 
 * Google Form column names:
 * - Timestamp: "03/11/2025 08:54:07"
 * - Full Name: "Robert T Kearney"
 * - Phone Number: "509-432-7356"
 * - Email Address: "Robert@Kearney.com"
 */

const newEntry = $input.first().json;

// Extract patient data using EXACT Google Form column names
const patientName = newEntry["Full Name"] || "Patient";
const patientEmail = newEntry["Email Address"] || "";
const patientPhone = newEntry["Phone Number"] || "";
const timestamp = newEntry["Timestamp"] || new Date().toISOString();

// Validate email exists
if (!patientEmail) {
  console.error("❌ No email provided, cannot send confirmation");
  return [];
}

// Parse timestamp for friendly display
// Google Forms format: "03/11/2025 08:54:07" (MM/DD/YYYY HH:MM:SS)
let signupDate = "today";
try {
  // Handle Google Forms date format
  const date = new Date(timestamp);
  signupDate = date.toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });
} catch (error) {
  console.error("Error parsing timestamp:", error.message);
  signupDate = timestamp; // Fallback to raw timestamp
}

// Get all waitlist entries to calculate position
const allEntries = $input.all();
const position = allEntries.length; // Simple position (last = newest)

// Extract first name for personalized email
const firstName = patientName.split(' ')[0];

console.log(`
📋 New Waitlist Signup:
  - Name: ${patientName}
  - Email: ${patientEmail}
  - Phone: ${patientPhone}
  - Position: #${position}
  - Signed up: ${signupDate}
  - Timestamp (raw): ${timestamp}
`);

return [{
  json: {
    patientName,
    patientEmail,
    patientPhone,
    signupDate,
    timestamp,
    waitlistPosition: position,
    firstName
  }
}];
